window.__wcagPrev = {
  htmlLang: document.documentElement.getAttribute('lang'),
  headHTML: document.head.innerHTML,
  bodyHTML: document.body.innerHTML
};
const rules = Object.keys(m.axeHandlers);
const results = await axe.run({
  rules: {
    'duplicate-id': { enabled: true },
    'duplicate-id-aria': { enabled: true },
    'duplicate-id-active': { enabled: true }
  },
  runOnly: { type: 'rule', values: rules }
});
for (const violation of results.violations) {
  const handler = m.axeHandlers[violation.id];
  if (!handler) continue;
  for (const node of violation.nodes) {
    try {
      const selector = Array.isArray(node.target) ? node.target.join(' ') : node.target;
      const el = document.querySelector(selector) || document.querySelector(node.target[0]);
      if (el) await handler(el, options);
    } catch (e) {
      console.error('Handler error for rule ' + violation.id + ':', e);
    }
  }
}
// axe passes the lone 16px help link (2.5.8's spacing exception), so
// hand it to the target-size handler directly.
const small = document.getElementById('small-target');
if (small) await m.axeHandlers['target-size'](small, options);

